# GT/pages/ui.R  --  The GT user interface: the folders, the Standard pages, the set-up flow pages and ui.
# Sourced by app.R at the top level (local = TRUE); the Workbench (workbench/wb_gt.R) reuses these pages.

if (dir.exists(file.path(APP_DIR, "docs"))) addResourcePath("docs", file.path(APP_DIR, "docs"))
# The folders (Home in the Standard interface, Import data in the Workbench).
std_folders <- function() fluidRow(column(7, div(class = "panel-x", h3("Folders"),
          textAreaInput("raw_dirs", "Data folders, one per line (any layout: rbr/2024, cryogeek/2024 ... or everything in one folder)", paste(SETTINGS$raw_dirs, collapse = "\n"), rows = 2, width = "100%"),
          ovid_browse_button("raw_dirs"), uiOutput("raw_check"),
          textInput("metadata_dir", "Metadata folder, optional (registry workbook, NTGS metadata workbooks, field notes; or use the deployment sheet)", SETTINGS$metadata_dir, width = "100%"), ovid_browse_button("metadata_dir"), uiOutput("meta_check"),
          textInput("project_dir", "Working (project) folder: set-up tables and output are kept here", SETTINGS$project_dir, width = "100%"), ovid_browse_button("project_dir"))),
          column(5, div(class = "panel-x flat", h3("How the folders are read"),
            tags$ul(class = "dim", tags$li("Every file under the data folders is looked at, in any sub-folder. What it is comes from its contents, not its name."),
                    tags$li("Each download is grouped with its exports: an RBR .hex with its Ruskin .txt/.xls, a GeoPrecision .f2b with its FG2-Shell .csv, a .hobo with its HOBOware .csv. RBR .hex files are read directly; the others from their export."),
                    tags$li("Campbell TOA5 .dat files can sit in the same folders: their temperature columns are taken (patterns under Quality rules > Campbell columns)."),
                    tags$li("The working folder can be anywhere, and several working folders can share one data folder. Each keeps its own set-up and output.")))))
std_css <- function() paste(mi_css, legible_css())
std_head <- function() tagList(if (exists("useBusyIndicators", asNamespace("shiny"))) shiny::useBusyIndicators(spinners = FALSE, pulse = TRUE),
                 if (VIEWER) tags$script(HTML("document.addEventListener('DOMContentLoaded',function(){document.documentElement.classList.add('viewer')});")))
# The Standard pages: the tools and section labels for ovid_page(), in rail order. The Workbench shows the same pages in
# its own frame (workbench/wb_gt.R); there sources = FALSE leaves the folders off Home, as its Import view holds them.
# The site table (landcover, group, location): the Sites page, and in the set-up flow the Sites step with renaming and what shows.
SITES_LEDE <- "One row per site: its group (sites that are compared together), landcover, instrument, location and installation details. A site holds one instrument type; loggers of different types are never merged, even with similar names."
gt_sites_ui <- function() tagList(
  div(class = "panel-x editor-only", fluidRow(column(5, selectizeInput("st_sites", "Sites", choices = NULL, multiple = TRUE, width = "100%")),
                                              column(3, selectInput("st_lc", "Landcover", LANDCOVERS, width = "100%")), column(4, textInput("st_group", "Site group (optional)", width = "100%"))),
      div(class = "btnrow", actionButton("st_apply", "Set for the selected sites", class = "btn-primary"))),
  editUI("sites"))

std_pages <- function(sources = TRUE) list(
    ovid_tool("Home", icon = "house",
      tagList(h2("Ground temperature hub"), p(class = "lede", "Every RBR, GeoPrecision, HOBO, EM50 and Campbell download in one place: stitched by serial across downloads, given depths and sites, checked, and summarised. Raw files are never changed; every value that is left out is in the audit trail.")),
      uiOutput("stats"),
      h4("Sites"), p(class = "dim", "Click a row to open it in Plot and explore."), DTOutput("home_sites"),
      h4("What each logger covers"),
      div(class = "scrollbox", plotOutput("coverage", height = "auto")),
      if (!VIEWER) fluidRow(
        column(6, div(class = "d-cardx", h3("Next time"), p("Put the new downloads from the field into one of the raw folders and press ", tags$b("Run pipeline"),
            ". Loggers whose files and set-up have not changed are reused; everything set up here is used again."),
          tags$a(href = "#", `data-ovid-go` = "Files", "Bring in new files \u203a"))),
        column(6, div(class = "d-cardx", h3("Recent changes"), uiOutput("saved_hist")))),
      if (!VIEWER && sources) p(class = "dim", "The data folders are on ", tags$a(href = "#", `data-ovid-go` = "Project", "1 Project"), "."),

      tags$details(class = "editor-only", tags$summary("Log of the last run"), uiOutput("log")),
      div(class = "foot", "Output is written to the working folder: output/sites (one record per site), output/soil, output/summaries, output/audit (audit trail and catalogue).")),

    "View",
    ovid_tool("Plot and explore", value = "Explore", icon = "chart-area",
      page_head("Plot and explore", "One site at a time. Every view reads the same cleaned record. On Over time (every depth together, or one panel per depth with the flagged and removed points), drag across the plot to select a stretch (drag up a panel's value axis to narrow it to a band of temperatures); the bar above it zooms in, removes or flags the points, removes a depth or every depth in the period, or trims the start or end of the record."),
      ovid_controls(
        selectInput("ex_site", "Site", choices = NULL, width = "100%"),
        suppressWarnings(dateRangeInput("ex_dates", "Period", start = NA, end = NA, width = "100%")),
        selectInput("ex_res", "Time step", res_choices, "day", width = "100%"),
        tagAppendAttributes(selectizeInput("ex_depths", "Depths (blank = all)", choices = NULL, multiple = TRUE, width = "100%", options = list(placeholder = "All depths")), class = "d-wide"),
        more = div(class = "btnrow", actionLink("ex_all", "Whole record"), actionLink("ex_lastyr", "Last 12 months"), actionLink("ex_lastwy", "Last water year")),
        more_label = "Period"),
      uiOutput("ex_site_note"),
      tabsetPanel(id = "ex_tab",
        tabPanel("Heatmap",
          tags$details(class = "d-drawer", tags$summary(icon("sliders"), " Plot options"), fluidRow(
            column(2, radioButtons("hm_interp", "Draw", c("Interpolated contours" = "TRUE", "One band per sensor" = "FALSE"), "TRUE")),
            column(2, numericInput("hm_dz", "Depth step (cm)", 5, min = 1, max = 50, width = "100%"), numericInput("hm_smooth", "Smooth over (time steps; 0 = off)", 7, min = 0, max = 31, width = "100%"),
                   p(class = "dim", "Drawing only: values, statistics and the gridded-values CSV never change. 0 draws what the Workbench draws.")),
            column(3, radioButtons("hm_scale", "Colour range", setNames(c("auto", "fixed", "sym"), c("Auto (1st to 99th percentile)", "Fixed", "\u00b1 around 0")), "auto"),
                   conditionalPanel("input.hm_scale == 'fixed'", fluidRow(column(6, numericInput("hm_lo", "From", -15, width = "100%")), column(6, numericInput("hm_hi", "To", 20, width = "100%"))))),
            column(3, textInput("hm_iso", "Extra isotherms (\u00b0C, comma separated)", "-5, 2, 5", width = "100%"), radioButtons("hm_trans", "Depth axis", c("Linear" = "linear", "Square root (stretch the shallow sensors)" = "sqrt"), "linear")),
            column(2, ovid_switch("hm_zero", "0 \u00b0C isotherm", TRUE), ovid_switch("hm_lines", "Mark sensor depths", TRUE)))),
          div(class = "btnrow", span(class = "push"), downloadButton("hm_png", "Export plot (PNG)"), downloadButton("hm_dl", "Export gridded values (CSV)")),
          ovid_focus(plotOutput("hm_plot", height = "560px"))),
        tabPanel("Over time",
          div(class = "btnrow", radioButtons("ot_view", NULL, c("Every depth together" = "all", "One panel per depth, with flagged and removed points" = "panels"), "all", inline = TRUE),
              conditionalPanel("input.ot_view != 'all'", ovid_switch("ot_same", "One axis for every depth", FALSE)), span(class = "push"), downloadButton("ex_dl", "Export these values (CSV)")),
          ts_viewbar(), ts_view("ot_tsv", 200),
          h4("Flags on this site"), DTOutput("qc_flags"), h4("What was removed from this site, and why"), DTOutput("qc_removed")),
        tabPanel("Box plots",
          tags$details(class = "d-drawer", tags$summary(icon("sliders"), " Plot options"), fluidRow(column(3, selectInput("bx_group", "Group by", BOX_GROUPS, "month", width = "100%")),
                                        column(3, radioButtons("bx_layout", "Layout", c("Side by side at each depth" = "dodge", "One panel per depth" = "facet"), "facet")),
                                        column(6, axis_ui("bx")))),
          p(class = "dim", "The time step above sets what each box summarises (every reading, hourly, daily, weekly or monthly means); Group by splits the record by year, water year, season or month."),
          div(class = "btnrow", span(class = "push"), downloadButton("bx_png", "Export plot (PNG)"), downloadButton("bx_dl", "Export box statistics (CSV)")),
          ovid_focus(uiOutput("bx_plot_ui")), h4("Box statistics"), DTOutput("bx_tbl")),
        tabPanel("Profile on dates",
          tags$details(class = "d-drawer", tags$summary(icon("sliders"), " Plot options"), fluidRow(column(6, selectizeInput("pd_dates", "Dates (daily means; type to add)", choices = NULL, multiple = TRUE, width = "100%", options = list(placeholder = "Pick one or more days"))),
                                        column(3, actionButton("pd_season", "Mid-month of the last year", icon = icon("calendar"))), column(3, axis_ui("pdx")))),
          ovid_focus(plotOutput("pd_plot", height = "560px")), div(class = "btnrow", span(class = "push"), downloadButton("pd_png", "Export plot (PNG)"))),
        tabPanel("Trumpet curves",
          tags$details(class = "d-drawer", tags$summary(icon("sliders"), " Plot options"), fluidRow(column(3, radioButtons("tr_yt", "Year", c("Calendar" = "calendar", "Water year (October to September)" = "water"), "calendar")),
                                        column(3, selectizeInput("tr_years", "Years (blank = all)", choices = NULL, multiple = TRUE, width = "100%")),
                                        column(3, radioButtons("tr_layout", "Layout", c("One panel per year" = "facet", "All years on one panel" = "overlay"), "facet"), ovid_switch("tr_complete", "Complete years only", FALSE)),
                                        column(3, axis_ui("trx")))),
          ovid_focus(uiOutput("tr_plot_ui")), div(class = "btnrow", span(class = "push"), downloadButton("tr_png", "Export plot (PNG)")), h4("Annual statistics"), DTOutput("tr_tbl")),
        tabPanel("Seasons and years",
          tags$details(class = "d-drawer", tags$summary(icon("sliders"), " Plot options"), fluidRow(column(3, selectInput("se_depth", "Depth", choices = NULL, width = "100%")),
                                        column(3, radioButtons("se_axis", "Year runs", c("October to September" = "water", "January to December" = "calendar"), "water")),
                                        column(3, selectInput("se_hl", "Highlight a year (climatology)", choices = NULL, width = "100%")), column(3, axis_ui("sex")))),
          ovid_focus(plotOutput("se_plot", height = "440px")), plotOutput("cl_plot", height = "380px"), plotOutput("an_plot", height = "380px")),
        tabPanel("Freeze and thaw",
          ovid_focus(plotOutput("ft_plot", height = "auto")), plotOutput("td_plot", height = "380px"),
          h4("Freeze / thaw dates by depth and water year"), DTOutput("ft_tbl"), h4("Zero-curtain periods"), DTOutput("zc_tbl")),
        tabPanel("Data availability", ovid_focus(plotOutput("av_plot", height = "auto")), h4("Gaps in this site's loggers"), DTOutput("av_gaps"))),

      h4("This site, by depth"), DTOutput("ex_stats")),

    ovid_tool("Compare sites", value = "Compare", icon = "code-compare",
      page_head("Compare sites", "The same depth at several sites. Pick sites with similar sensors (filter by instrument and site group); each site contributes its sensor nearest the depth chosen."),
      ovid_controls(
        tagAppendAttributes(selectizeInput("cp_sites", "Sites", choices = NULL, multiple = TRUE, width = "100%", options = list(placeholder = "Pick two or more")), class = "d-wide"),
        numericInput("cp_depth", "Depth (m, as the set-up tables are typed)", 0.5, step = 0.05, width = "100%"),
        selectInput("cp_res", "Time step", res_choices[-1], "day", width = "100%"),
        selectInput("cp_mode", "Show", c("Values" = "value", "Difference from a reference site" = "diff", "Difference from each site's own mean" = "anomaly"), width = "100%"),
        ovid_split_toggle("cp_split", "Plot and summary"),
        more = tagList(selectizeInput("cp_type", "Instrument", choices = NULL, multiple = TRUE, width = "100%", options = list(placeholder = "All instruments")),
                       selectizeInput("cp_group", "Site group or landcover", choices = NULL, multiple = TRUE, width = "100%", options = list(placeholder = "All")),
                       numericInput("cp_tol", "Match within (m)", 0.1, min = 0, step = 0.05, width = "100%"),
                       selectInput("cp_kind", "Plot", c("Time series" = "line", "Scatter of two sites" = "scatter"), width = "100%"),
                       conditionalPanel("input.cp_mode == 'diff'", selectInput("cp_ref", "Reference site", choices = NULL, width = "100%")),
                       suppressWarnings(dateRangeInput("cp_dates", "Period (blank = everything)", start = NA, end = NA, width = "100%")),
                       axis_ui("cpx"),
                       div(class = "btnrow", downloadButton("cp_png", "Export plot (PNG)"), downloadButton("cp_dl", "Export these values (CSV)")))),
      ovid_split("cp_split", width = "34%", ovid_focus(plotOutput("cp_plot", height = "520px")), tableOutput("cp_stats"), side_title = "Summary by site"),
      h4("Annual statistics side by side"), DTOutput("cp_annual"),
      h4("Between-site check"),
      p(class = "dim", "Every depth that three sites or more share, compared day by day with the median of the other sites. Sites differ by a steady amount that changes with the season, so only a sudden departure from that counts; such days are flagged (kept) in the audit trail. ",
        tags$b("out of step"), ": the site's weekly changes hardly follow the others' (a clock, depth or site mix-up, or a sensor in air or water). Click a row to see it."),
      DTOutput("bs_tbl"), ovid_focus(plotOutput("bs_plot", height = "420px"))),

    ovid_tool("Summaries", value = "Summ", icon = "table-cells",
      page_head("Summaries", "From daily means. A day counts when it holds enough readings, a year when it holds enough complete days (Settings). Incomplete years are kept but marked."),
      ovid_controls(tagAppendAttributes(selectizeInput("sm_sites", "Sites (blank = all)", choices = NULL, multiple = TRUE, width = "100%"), class = "d-wide"),
                      radioButtons("sm_yt", "Year", c("Calendar" = "calendar", "Water year" = "water"), "calendar", inline = TRUE),
                      ovid_switch("sm_complete", "Complete years only", FALSE)),
      tabsetPanel(
        tabPanel("A. Annual statistics", p(class = "dim", "Mean (MAGT), minimum, maximum and range of the daily means at each depth; the dates of the minimum and maximum."), DTOutput("sm_annual"),
                 h4("Depth of zero annual amplitude"), p(class = "dim", "The shallowest depth whose annual range is below 0.1 \u00b0C (blank when no sensor is that deep)."), DTOutput("sm_zaa")),
        tabPanel("B. Active-layer thickness", p(class = "dim", "The deepest the 0 \u00b0C line reaches in the year, interpolated linearly between the two sensors around it. Reported only where permafrost is present within the sensors (a depth stays at or below 0 \u00b0C all year); otherwise the reason is given. Its accuracy is limited by the sensor spacing."),
                 DTOutput("sm_alt"), plotOutput("sm_alt_plot", height = "380px")),
        tabPanel("C. Freeze / thaw and zero curtain", p(class = "dim", "Per depth and water year (", textOutput("sm_wy", inline = TRUE), "): first and last day at or below 0 \u00b0C, the first day above 0 \u00b0C after that, and days frozen, thawed and in the zero curtain."),
                 DTOutput("sm_ft"), h4("Zero-curtain periods"), DTOutput("sm_zc")),
        tabPanel("D. Degree days and n-factors", p(class = "dim", "Freezing and thawing degree days (sums of the daily means below and above 0 \u00b0C) per water year; n-factors (surface over air), and the surface offset (MAGST \u2212 MAAT). Air temperature comes from a sensor above the ground at the site, or from a CSV named in air_temperature.csv (Quality rules > Air temperature); without it only the ground values are given."),
                 h4("n-factors and the surface offset"), DTOutput("sm_nf"), h4("Degree days by series"), DTOutput("sm_dg")),
        tabPanel("E. Ground state and taliks", p(class = "dim", "Each depth per complete year: permafrost (at or below 0 \u00b0C all year, two years in a row), seasonally frozen, or perennially unfrozen. A supra-permafrost talik is a layer unfrozen all year between the seasonal frost and permafrost; its top and bottom are where the year's minimum and maximum cross 0 \u00b0C. The whole profile is scanned."),
                 h4("Taliks"), DTOutput("sm_talik"), h4("State of each depth"), DTOutput("sm_gstate")),
        tabPanel("F. Trends", p(class = "dim", "Theil-Sen slope (per decade) and the Mann-Kendall test on MAGT at each depth and on the active-layer thickness, over complete years (at least the minimum set in Settings); with ten years or more the test allows for autocorrelation (Hamed and Rao 1998)."), DTOutput("sm_trend"),
                 h4("Sensor offsets in the zero curtain"), p(class = "dim", "In saturated ground the zero curtain holds near 0 \u00b0C, so a sensor's median there estimates its offset. A field check: listed, never applied."), DTOutput("sm_zoff")),
        tabPanel("G. Diffusivity, gradient, gaps", p(class = "dim", "The annual temperature wave at each depth (complete calendar years) gives an apparent thermal diffusivity between two sensors, from how fast the wave shrinks (amplitude) and how late it arrives (phase). Conduction alone gives the same value both ways; where they differ by more than 2x, latent heat or moving water is at work. Typical soils: 0.1 to 1 mm\u00b2/s. The gradient is the change of the annual mean with depth; ", code("deepest"), " marks the deepest pair."), DTOutput("sm_thermal"),
                 h4("Estimated days"), p(class = "dim", "Missing daily means that were estimated (level L3): short gaps at depth linearly in time, longer ones from the sensors above and below when they track it closely. Measured days are never replaced; annual statistics use these only if that is switched on (Automatic corrections)."), DTOutput("sm_est")))),

    ovid_tool("Soil moisture and EC", value = "Soil", icon = "droplet",
      page_head("Soil moisture and conductivity", "Volumetric water content and bulk electrical conductivity from the EM50s (and any Campbell soil probes), kept apart from ground temperature."),
      ovid_controls(selectInput("so_site", "Site", choices = NULL, width = "100%"), radioButtons("so_var", "Show", c("Water content" = "vwc", "Conductivity" = "ec"), "vwc", inline = TRUE),
                      selectInput("so_res", "Time step", res_choices, "day", width = "100%"),
                      radioButtons("so_axis", "Axis", setNames(c("auto", "vwc"), c("Auto", "0 to 0.6 m\u00b3/m\u00b3")), "auto", inline = TRUE)),
      uiOutput("so_empty"), ovid_focus(plotOutput("so_plot", height = "480px")), plotOutput("so_temp", height = "320px"), div(class = "btnrow", span(class = "push"), downloadButton("so_png", "Export plot (PNG)")), DTOutput("so_tbl")),

    ovid_tool("Site details", value = "Site", icon = "location-dot",
      page_head("Site details", "Everything known about one site: set-up, installation and location (from the Sites page and every metadata workbook), the record, statistics by depth, the sensors and their depths, and field notes that mention it."),
      selectInput("sd_site", "Site", choices = NULL, width = "360px"),
      div(class = "cards", div(class = "panel-x", h3("Site and installation"), uiOutput("sd_site_ui")), div(class = "panel-x", h3("Record"), uiOutput("sd_record_ui"))),
      h4("Statistics by depth"), DTOutput("sd_stats"),
      h4("Sensors and depths"), DTOutput("sd_sensors"),
      h4("Every metadata field found for this site"), DTOutput("sd_meta"),
      h4("Field notes that mention this site or its loggers"), uiOutput("sd_notes")),

    "Data",
    ovid_tool("Raw files", value = "Files", icon = "folder-open",
      page_head("Raw files", "Every file found, what it is, and which file each download is read from. A download whose only file cannot be read is listed as needing an export."),
      tabsetPanel(
        tabPanel("Downloads", p(class = "dim", "One row per download: the logger's own file and its exports. ", tags$b("source_file"), " is the one read."),
                 DTOutput("rf_bundles"), h4("RBR .hex checked against its Ruskin export"), DTOutput("rf_xchk")),
        tabPanel("All files", div(class = "btnrow", radioButtons("rf_show", NULL, inline = TRUE, c("All" = "all", "Read" = "used", "Not read" = "unused", "Needs attention" = "bad"))),
                 DTOutput("rf_tbl"),
                 div(class = "panel-x editor-only", h3("Sort the selected files"), fluidRow(column(3, textInput("rf_serial", "Serial (for Set serial)", width = "100%")),
                   column(6, textInput("rf_reason", "Reason", width = "100%")), column(3, textInput("rf_author", "Your initials", width = "100%"))),
                   div(class = "btnrow", actionButton("rf_ignore", "Leave out", icon = icon("ban")), actionButton("rf_use", "Use this copy too", icon = icon("check")), actionButton("rf_setserial", "Set serial"))),
                 div(class = "panel-x editor-only", h3("Rescan the selected files"), p(class = "dim", "Reads the selected files again and rebuilds only their loggers and sites; everything else is reused from the last run."),
                   div(class = "btnrow", actionButton("rf_rescan", "Rescan selected files", icon = icon("rotate"), class = "btn-primary")))),
        tabPanel("File rules", p(class = "dim", code("pattern"), ": a file name or a regular expression on the path. ", code("action"), ": ignore, use or serial."), editUI("frules")))),

    ovid_tool("Sensor health", value = "Health", icon = "heart-pulse",
      page_head("Sensor health", "Every sensor of every logger: how many values it wrote, how many were errors (a failed thermistor, a dead node, a broken port), how many were removed or flagged, and its gaps. Malfunctioning sensors show here first."),
      uiOutput("he_cards"),
      div(class = "btnrow", radioButtons("he_show", NULL, inline = TRUE, c("Needing attention" = "bad", "All" = "all"))), DTOutput("he_tbl"),
      h4("Gaps"), p(class = "dim", "Holes longer than the gap limit (Settings, Advanced) in logging intervals."), DTOutput("he_gaps"),
      h4("Logger events"), p(class = "dim", "Tags written by GeoPrecision loggers (new parameters, read-outs, firmware resets), HOBO events (battery, end of file) and RBR time-stamp events."), DTOutput("he_events"),
      h4("Battery (GeoPrecision)"), plotOutput("he_bat", height = "300px")),

    ovid_tool("Clock checks", value = "Clock", icon = "clock",
      page_head("Clock checks", paste0("Every time stamp is moved to ", zone_text(BASE_OFFSET), " (the time zone in Settings) without daylight saving. Ruskin text exports are in UTC and are converted; HOBOware states its zone; other loggers' clocks are taken as ", zone_text(BASE_OFFSET), " unless the time-zone table says otherwise.")),
      h4("Clock faults and drift"), p(class = "dim", tags$b("clock_reset"), ": readings after the clock jumped back (cannot be placed in time). ", tags$b("clock_resync"), ": earlier readings superseded after the clock was set back. ",
                                      tags$b("clock_drift"), ": RBR logger time against the computer at download (positive = logger slow); switch on Correct RBR clock drift on the Automatic corrections step to spread it over the record."),
      DTOutput("ck_tbl"), h4("Zone each file was read in"), DTOutput("ck_files"),
      fluidRow(column(6, h4("Time zones"), p(class = "dim", "Set the zone a logger's clock was in, for many files at once. Fill in any of ", code("serial"), ", ", code("model"), " (part of the name, e.g. U12), ", code("file_pattern"), " (a folder or part of the path) and ", code("start"), "/", code("end"), " (the file's first reading falls in this span); blank matches anything. ", code("offset_hours"), ": -7, 0, -6 ... A row here wins over the zone a file states. The first matching row wins."), editUI("tz")),
               column(6, h4("Clock corrections"), p(class = "dim", code("shift_minutes"), " moves the readings of ", code("serial"), " between ", code("start"), " and ", code("end"), " (base time; blank = all)."), editUI("time")))),

    ovid_tool("Audit trail", value = "Audit", icon = "clipboard-check",
      page_head("Audit trail", "Nothing leaves the data without a line here. The value count of every logger sensor is reconciled at the end of each run: read = kept + removed."),
      uiOutput("au_cards"),
      h4("1. What was done, and why"), p(class = "dim", "Click a line to see what it means."), DTOutput("au_rules"), uiOutput("au_explain"),
      h4("2. Where it happened"), DTOutput("au_where"),
      h4("3. Reconciliation by logger sensor"), DTOutput("au_recon"),
      h4("4. Every raw file"), p(class = "dim", "Each file found, its checksum (md5), how many values were read from it, how many reached a site record (or the battery table), and how many were dropped and why: a duplicate download, a clock reset, outside a deployment, or a quality rule. ",
        code("reconciles"), " checks read = in output + dropped for every file that was read."), DTOutput("au_files"),
      h4("5. Every download"), p(class = "dim", "A download is the logger's own file with its exports; one of them is read. The same check, added up per download."), DTOutput("au_bundles")),

    "Set up",
    ovid_tool("Sites and landcover", value = "Sites", icon = "map-location-dot",
      page_head("Sites and landcover", SITES_LEDE), gt_sites_ui()),

    ovid_tool("Sensors and depths", value = "Sensors", icon = "ruler-vertical",
      page_head("Sensors and depths", "One row per sensor and deployment: make, model, serial, the sensor (channel), its depth in metres below the surface (negative = above), the site, and the dates it was there. Depths come from here first; a sensor with no depth gets one from a template for its model, else the default steps (Settings), and is marked as assumed."),
      div(class = "panel-x", group_by_ui("gb")),                       # the logger list grouped by serial, deployment, download or file (core grouping.R)
      tabsetPanel(id = "sn_tab",
                  tabPanel("Deployment sheet", uiOutput("ll_depth_note"), meta_sheet_ui("mlist", LOGGER_LIST_INTRO),
                           p(class = "dim", "Matches that are only guesses (a year, a name in the files, a logger's only deployment) wait in ", tags$a(href = "#", `data-ovid-go` = "Needs", "4 Needs you"), ".")), tabPanel("Sensors", editUI("sensors")),
