                       "Above the ground positive: 0.5 is 0.5 m up, -1.2 is 1.2 m down" = "up"), if (identical(SETTINGS$depth_positive, "up")) "up" else "down", width = "100%"),
          p(class = "dim", "A depth written with + (e.g. +0.3) is always above the ground. The same convention holds for manual removals, Compare sites and the export. Changing this re-reads every depth at the next run; the numbers you typed stay as they are."))),
        column(4, div(class = "panel-x", h3("Summaries"),
          numericInput("min_complete", "Share of a day's readings needed for a daily mean", SETTINGS$min_complete, min = 0, max = 1, step = 0.05, width = "100%"),
          numericInput("year_complete", "Share of a year's days needed for a complete year", SETTINGS$year_complete, min = 0, max = 1, step = 0.05, width = "100%"),
          numericInput("water_year_start", "Water year starts in month", SETTINGS$water_year_start, min = 1, max = 12, step = 1, width = "100%"),
