          numericInput("zero_curtain_days", "... for at least this many days", SETTINGS$zero_curtain_days, step = 1, width = "100%"),
          numericInput("trend_min_years", "Trends need at least this many complete years", SETTINGS$trend_min_years, step = 1, width = "100%"),
          selectInput("permafrost_years", "Permafrost test (consecutive frozen years)", setNames(PERMAFROST_YEARS, PERMAFROST_YEARS), SETTINGS$permafrost_years %||% PERMAFROST_YEARS_DEFAULT, width = "100%"),
          p(class = "dim", "2 follows the permafrost definition (van Everdingen 1998); 1 is the one-year test used before.")))),
      tags$details(class = "d-drawer", tags$summary("Advanced"), p(class = "dim", "Expert limits for the quality checks and gap filling. The defaults suit most projects; change them only with a reason. Depths are metres below the ground."),
        fluidRow(column(4,
          numericInput("min_year", "Clock reset: flag time stamps before (year)", SETTINGS$min_year, step = 1, width = "100%"),
          numericInput("gap_factor", "Gap: interval longer than (\u00d7 logging interval)", SETTINGS$gap_factor, step = 0.5, width = "100%"),
          numericInput("spike_k", "Spike: step larger than (robust SD of the sensor's usual step)", SETTINGS$spike_k, step = 1, width = "100%"),
          numericInput("zero_offset_limit", "Zero-curtain offset: list sensors whose zero-curtain median is further from 0 \u00b0C than (\u00b0C)", SETTINGS$zero_offset_limit, step = 0.05, width = "100%"),
          p(class = "dim", "Indicates a calibration offset."),
          numericInput("surface_max_depth", "Ground-surface temperature: shallowest sensor at depth up to (m)", SETTINGS$surface_max_depth, step = 0.05, width = "100%")),
                 column(4, h4("Gap filling"),
          numericInput("fill_gap_days", "Linear in time for gaps up to (days)", SETTINGS$fill_gap_days, step = 1, width = "100%"),
          numericInput("fill_min_depth", "... at depth from (m)", SETTINGS$fill_min_depth, step = 0.1, width = "100%"),
          numericInput("fill_r2_min", "Longer gaps by regression on adjacent sensors when r\u00b2 is at least", SETTINGS$fill_r2_min, step = 0.01, width = "100%"),
          p(class = "dim", "Shallower sensors follow air temperature too closely for linear fill. Estimated days go to daily_estimated.csv.")),
                 column(4, h4("Air-like readings"),
          numericInput("air_like_daily_range", "Flag days with a daily range above (\u00b0C)", SETTINGS$air_like_daily_range, step = 1, width = "100%"),
          numericInput("air_like_min_depth", "... at depth from (m)", SETTINGS$air_like_min_depth, step = 0.05, width = "100%"),
          p(class = "dim", "A buried sensor cannot vary this much in a day; it is likely exposed."),
          h4("Pre-installation"),
          numericInput("pre_install_spread", "Flag the record start while all sensors read within (\u00b0C)", SETTINGS$pre_install_spread, step = 0.05, width = "100%"),
          numericInput("pre_install_days", "... searched in the first (days)", SETTINGS$pre_install_days, step = 1, width = "100%"),
          p(class = "dim", "Before burial, all sensors on a string are in the same air and read the same. Needs at least 3 sensors agreeing for 6 h."))),
        p(class = "dim", "The on/off switch for each check is on the Automatic corrections step.")),
      div(class = "panel-x", h3("Colours"), colours_ui()),
      projects_panel()),

    "Report",
    ovid_tool("Reports and export", value = "Export", icon = "file-export",
      page_head("Reports and export", "One zip that can be used without the app: each site's ground temperature with flag columns, soil moisture, the summaries, the site and sensor metadata, the audit trail and a readme."),
      div(class = "panel-x", fluidRow(
        column(6, selectizeInput("xp_sites", "Sites", choices = NULL, multiple = TRUE, width = "100%", options = list(placeholder = "Pick one or more (blank = all)")),
               suppressWarnings(dateRangeInput("xp_dates", "Period (blank = everything)", start = NA, end = NA, width = "100%"))),
        column(2, radioButtons("xp_res", "Time step", res_choices, "raw")),
