        column(2, numericInput("xp_tz", "Time zone of the export (UTC offset, hours)", BASE_OFFSET, step = 1, width = "100%"), checkboxInput("xp_soil", "Soil moisture and EC", TRUE),
               checkboxInput("xp_summ", "Summaries", TRUE), checkboxInput("xp_audit", "Audit trail", TRUE),
               checkboxInput("xp_nc", "NetCDF too (CF-1.10, for GTN-P and PermafrostNet)", FALSE))),
        div(class = "btnrow", downloadButton("xp_dl", "Build and export (ZIP)", class = "btn-primary")),
        p(class = "dim", "The run report (downloads, loggers, sites, clock events, sensor health, removals, problems) or one site (depths and where they came from, active layer, freeze and thaw, annual statistics, heatmap and trumpet curves); every report is the run report and one per site above, as a ZIP."),
        div(class = "btnrow", selectInput("rp_pick", "Report (run report or a site; HTML or PDF)", choices = report_choices(), width = "420px"),
            downloadButton("rp_dl", "Export report"))),
      report_options_ui("rpo", GT_REPORT_SECTIONS),
      div(class = "explain", tags$b("Flags"), tags$br(), "Each value is kept or removed; kept values may carry flags (the checks that marked them as suspect), separated by ;. Removed values are not in the export; they are in audit/audit_index.csv with the reason. ",
          tags$b("depth_source"), " says whether a depth was given (manual, registry) or assumed (template, default)."))
)
# The Standard view as the set-up flow (core 1.2), laid out as a notebook: five stages and nine shared steps with GT's own
# pages beside them, and the rest under More. The Workbench shows the same pages in its own frame (sources = FALSE: the
# folders are under its Import data).
# The site notebook (Standard, "Site results"): one site from its facts to its annual summary in one column, after the
# approved design. Site chips, the site's name and one line, four facts, then ground temperature by depth, thaw depth and
# the annual summary. It reads the same cleaned record and summaries as Plot and explore; smoothing is display only.
nb_ui <- function() tagList(
  tags$style(HTML(".nb-chips{display:flex;gap:6px;flex-wrap:wrap;align-items:center;margin:2px 0 14px}.nb-chip{padding:3px 10px;border:1px solid var(--bg3);border-radius:6px;color:var(--fg4);font-size:12.5px;text-decoration:none}
.nb-chip:hover{background:var(--bg1);color:var(--fg);text-decoration:none}.nb-chip.on{border-color:var(--acc);color:var(--fg);box-shadow:inset 0 0 0 1px var(--acc)}
.nb-chips .form-group{margin:0;width:140px}.nb-chips .selectize-input{min-height:28px;padding:3px 8px;border-radius:6px}
.nb-site{margin:0 0 2px;font-size:22px}.nb-desc{color:var(--fg4);margin:0 0 10px;max-width:880px}.nb-sech{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.nb-sech h3{margin:0 auto 0 0}
.nb-sech .form-group{margin:0}.nb-sech .shiny-options-group{display:flex;gap:4px}.nb-sech .radio-inline{margin:0;padding:0}.nb-sech .radio-inline input{display:none}.nb-sech .radio-inline span{display:inline-block;padding:2px 10px;border:1px solid var(--bg3);border-radius:6px;font-size:12.5px;cursor:pointer}
.nb-sech .radio-inline:has(input:checked) span{border-color:var(--acc);color:var(--fg);box-shadow:inset 0 0 0 1px var(--acc)}
.nb-depth{display:flex;align-items:center;gap:8px;margin:0 0 6px;font-size:12.5px;color:var(--fg4)}.nb-depth .form-group{margin:0;width:120px}")),
  tags$script(HTML("$(document).on('click','.nb-chip',function(e){e.preventDefault();Shiny.setInputValue('nb_pick',this.getAttribute('data-site'),{priority:'event'});});")),
  ovid_step_head(NULL, "Site results", "One site at a time: its facts, the ground temperature at every depth, the thaw depth and the annual summary. Everything here is read from the last run."),
  uiOutput("nb_chips"), uiOutput("nb_head"),
  div(class = "nb-depth", span("Mean ground temperature at"), selectInput("nb_depth", NULL, choices = NULL, width = "120px")),
  uiOutput("nb_facts"),
  div(class = "d-cardx", div(class = "nb-sech", h3("Ground temperature by depth"), span(class = "dim", "Smooth over (time steps; 0 = off)"),
        numericInput("nb_smooth", NULL, 7, min = 0, max = 31, width = "80px")),
      p(class = "dim", "Daily means, red above 0 \u00b0C and blue below. Smoothing only changes how this picture is drawn, never the values, statistics or exports."),
      ovid_focus(plotOutput("nb_hm", height = "380px")), uiOutput("nb_hm_cap")),
  div(class = "d-cardx", h3("Thaw depth"), ovid_focus(plotOutput("nb_td", height = "300px"))),
  div(class = "d-cardx", div(class = "nb-sech", h3("Annual summary by depth"), span(class = "dim", "Year"),
        div(style = "width:110px", selectInput("nb_year", NULL, choices = NULL, width = "110px"))),
      DTOutput("nb_annual")))

# The before-import screen (Standard, Project page, while there is no run yet): three equal choices and what the folders hold.
gt_before_ui <- function() conditionalPanel("!output.has_out", div(class = "bi",
  tags$style(HTML(".bi-three{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:0 0 12px}.bi-choice{display:flex;flex-direction:column;gap:6px}.bi-choice .btn{align-self:flex-start}
.bi-choice .d-browse,.bi-choice .btn{margin-top:4px}@media (max-width:1100px){.bi-three{grid-template-columns:1fr}}.bi-scan td,.bi-scan th{padding:3px 10px}.bi-scan .ok{color:var(--green)}.bi-scan .no{color:var(--yellow)}")),
  div(class = "bi-three",
    div(class = "d-cardx bi-choice", tags$b("Choose a data folder"), p(class = "dim", "GeoPrecision .f2b and CSV, RBR .hex and .txt, HOBO CSV, EM50 .xls, Campbell .dat. Repeat downloads of a logger are joined. Nothing in your folder is changed."),
        tags$a(class = "btn btn-default", href = "#", onclick = "var t=document.getElementById('raw_dirs'); if(t){t.scrollIntoView({block:'center'}); t.focus();} return false;", icon("folder-open"), " Choose folder…")),
    div(class = "d-cardx bi-choice", tags$b("Bring your own metadata"), p(class = "dim", "A CSV or Excel file of loggers, sites or depths. You say which column is which; the file is only read."),
        tags$a(class = "btn btn-default", href = "#", `data-ovid-go` = "Sensors", icon("table-list"), " Import a table…")),
    div(class = "d-cardx bi-choice", tags$b("Open a project"), uiOutput("bi_recent"),
        tags$a(class = "btn btn-default", href = "#", onclick = "var t=document.querySelector('.d-projsw'); if(t){t.open=true; t.scrollIntoView({block:'center'});} return false;", "Open the project menu"))),
  div(class = "d-cardx", h4("What the folders hold"), uiOutput("bi_scan"))))

gt_flow_pages <- function(sources = TRUE) {
  pg <- Filter(function(x) inherits(x, "ovid_tool"), std_pages(sources)); by <- setNames(pg, vapply(pg, `[[`, "", "value"))
  step <- function(v, n = NULL, title = NULL, icon = NULL) { x <- ovid_retitle(by[[v]], n, title); if (!is.null(x) && !is.null(icon)) x$icon <- icon; x }
  nxt <- function(label, go) ovid_next(paste("Next:", label), go)
  E <- !VIEWER
  list(
    ovid_stage(1, "Bring in"),
    if (E) ovid_tool("Project", value = "Project", icon = "folder-tree", n = 1,
      ovid_step_head(1, "Project", "Where the raw data are read from and where this project keeps its set-up tables and outputs. Raw files are never changed."),
      gt_before_ui(),
      if (sources) std_folders() else p(class = "dim", "The folders are under Import data in the Workbench."), nxt("Bring in files", "Files")),
    if (E) step("Files", 2, "Bring in files", "file-import"),
    ovid_stage(2, "Organize"),
    if (E) step("Sensors", 3, "Loggers, sensors and depths"),
    if (E) ovid_tool("Needs you", value = "Needs", icon = "circle-question", n = 4,
      ovid_step_head(4, "Needs you", "Only a match by dates is assigned on its own. Everything else (a year, a name in the files, a logger's only deployment) is a suggestion here, accepted with one click. Below them, what the last run flagged and found, each decided here."),
      deploy_check_ui("depcheck"), div(class = "d-cardx", h3("What the last run found"), review_list_ui("rl")), nxt("Sites: rename, what shows, landcover", "Sites")),
    # one step for renaming, what shows and the site table; it takes the Sites page's place (value), so links to Sites land here
    if (E) ovid_tool("Sites: rename, what shows, landcover", value = "Sites", icon = "map-location-dot", n = 5,
      ovid_step_head(5, "Sites: rename, what shows, landcover", "Rename a site once and it is renamed in every set-up table (with a preview and Undo). Choose which sites show on the strip, Home and Needs you (they are still processed and exported). Then each site's group, landcover and details."),
      div(class = "d-cardx", rename_ui("ren")), div(class = "d-cardx", h3("What shows"), display_ui("disp", "site")),
      div(class = "d-cardx", h3("Sites and landcover"), p(class = "dim", SITES_LEDE), gt_sites_ui())),
    ovid_stage(3, "Correct"),
    if (E) step("Clock", NULL, "Clocks"),
    if (E) step("QC", NULL, "Quality rules"),
    if (E) ovid_tool("Automatic corrections", value = "Corrections", icon = "wand-magic-sparkles", n = 6,
      ovid_step_head(6, "Automatic corrections", "Corrections every run makes on its own, each with a switch. They are on by default."),
      div(class = "d-cardx", corrections_ui("corr")), nxt("Report", "Export")),
    ovid_stage(4, "Report"),
    ovid_tool("Site results", value = "SiteNb", icon = "clipboard-list", nb_ui()),
    step("Summ", NULL, "Thaw depth and summaries"),
    step("Export", 7, "Report"),
    "More",
    step("Home", NULL, "Overview"), step("Explore"), step("Compare"), step("Soil"), step("Site"), step("Health"), step("Audit"), if (E) step("Config"),
    if (E) step("Preflight"), step("Settings"))
}

ui <- do.call(ovid_page, c(list("GT", MI, css = std_css(), head = std_head(),
  status = uiOutput("runstate", inline = TRUE),
  layout = "notebook", project = if (!VIEWER) projects_switch_ui("proj"), context = uiOutput("flow_ctx", inline = TRUE), aside = uiOutput("flow_info"),
  actions = tagList(applied_ui("applied"), if (!VIEWER) unsaved_ui("uns"),
                    if (VIEWER) span(class = "modebadge", "Viewer") else actionButton("run", "Run pipeline", class = "btn-primary", icon = icon("play"))),
  help = if (file.exists(file.path(APP_DIR, "docs", "GT_reference_guide.html"))) "docs/GT_reference_guide.html",
  settings = "Settings"), c(gt_flow_pages(), list(convert_tool(), reference_tool("GT")))))
